engine.analyze:
async function analyze(input, providers) {
  var settings = (input && input.settings) || {};
  var onLog = (input && typeof input.onLog === "function") ? input.onLog : function () { };
  var changes = [];
  var warnings = [];
  var totalWords = 0;

  // Run all the doc mutations inside one Word.run via runRaw. Keeps the
  // sync()  count low and lets us share `body` + `docRange` across steps.
  var report = await providers.host.runRaw("docuscrub", async function (context) {
    var body = context.document.body;
    var docRange = null;

    // Inner helper: search-and-replace with optional progress callback.
    async function searchReplace(find, replaceWith, opts, logId, flashTpl) {
      var sr = body.search(find, opts || {});
      sr.load("items");
      await context.sync();
      var count = sr.items.length;
      for (var i = 0; i < count; i++) {
        sr.items[i].insertText(replaceWith, "Replace");
        if (flashTpl) onLog({ kind: "flash", id: logId, n: i + 1, tpl: flashTpl });
      }
      return count;
    }

    if (settings.removeComments) {
      onLog({ kind: "step", id: "comments", icon: "⏳", text: "Removing comments..." });
      try {
        var comments = context.document.comments;
        comments.load("items");
        await context.sync();
        var commentCount = comments.items.length;
        var deleted = 0;
        for (var c = comments.items.length - 1; c >= 0; c--) {
          try { comments.items[c].delete(); deleted++; }
          catch (e2) { /* best effort */ }
        }
        if (commentCount > 0) changes.push({ icon: "💬", text: "Deleted " + commentCount + " comment(s)" });
        onLog({ kind: "step", id: "comments", icon: "💬", text: "Comments: " + commentCount + " deleted" });
      } catch (e) {
        onLog({ kind: "step", id: "comments", icon: "⚠️", text: "Comment removal failed", warn: true });
      }
    }

    if (settings.acceptRedlines) {
      onLog({ kind: "step", id: "redlines", icon: "⏳", text: "Accepting tracked changes (this may take a moment)..." });
      try {
        var attempt = 0;
        var acceptedCount = 0;
        // Body — retry up to 3× because nested redlines surface across syncs.
        while (attempt < 3) {
          var tc = context.document.body.getTrackedChanges();
          tc.load("items");
          await context.sync();
          if (tc.items.length === 0) break;
          for (var i = tc.items.length - 1; i >= 0; i--) {
            try { tc.items[i].accept(); acceptedCount++; } catch (e3) { /* skip */ }
          }
          await context.sync();
          attempt++;
        }
        // Headers + footers — separate sweep per section / type.
        try {
          var sections = context.document.sections;
          sections.load("items");
          await context.sync();
          var hfTypes = ["Primary", "FirstPage", "EvenPages"];
          for (var s = 0; s < sections.items.length; s++) {
            var sec = sections.items[s];
            for (var t = 0; t < hfTypes.length; t++) {
              try {
                var hdrTc = sec.getHeader(hfTypes[t]).getTrackedChanges();
                var ftrTc = sec.getFooter(hfTypes[t]).getTrackedChanges();
                hdrTc.load("items");
                ftrTc.load("items");
                await context.sync();
                for (var ii = hdrTc.items.length - 1; ii >= 0; ii--) {
                  try { hdrTc.items[ii].accept(); acceptedCount++; } catch (e4) { }
                }
                for (var jj = ftrTc.items.length - 1; jj >= 0; jj--) {
                  try { ftrTc.items[jj].accept(); acceptedCount++; } catch (e5) { }
                }
              } catch (e6) { /* skip section/type */ }
            }
          }
          await context.sync();
        } catch (ehf) { /* tolerate */ }
        if (acceptedCount > 0) changes.push({ icon: "🟢", text: "Accepted " + acceptedCount + " tracked change(s)" });
        onLog({ kind: "step", id: "redlines", icon: "🟢", text: "Tracked changes: " + acceptedCount + " accepted" });
      } catch (e) {
        onLog({ kind: "step", id: "redlines", icon: "⚠️", text: "Accept redlines failed: " + (e.message || e), warn: true });
      }
    }

    var needsFontOp =
      (settings.fontName && settings.fontName !== "NO_CHANGE") ||
      (settings.fontSize && settings.fontSize > 0) ||
      (settings.fontColor && settings.fontColor !== "" && settings.fontColor !== "#000000");

    if (needsFontOp) {
      onLog({ kind: "step", id: "font", icon: "⏳", text: "Unifying font styles..." });
      try {
        docRange = body.getRange();
        var fontOps = [
          { prop: "name", val: settings.fontName, skip: "NO_CHANGE", label: "Font set to " },
          { prop: "size", val: settings.fontSize, skip: 0, label: "Font size set to ", suffix: "pt" },
          { prop: "color", val: settings.fontColor, skip: "" },
        ];
        fontOps.forEach(function (op) {
          if (op.val && op.val !== op.skip) {
            docRange.font[op.prop] = op.val;
            if (op.label) changes.push({ icon: "🔤", text: op.label + op.val + (op.suffix || "") });
          }
        });
        await context.sync();
        onLog({ kind: "step", id: "font", icon: "🔤", text: "Font unified" });
      } catch (e) {
        onLog({ kind: "step", id: "font", icon: "⚠️", text: "Font step failed: " + (e.message || e), warn: true });
      }
    }

    if (settings.removeHighlighting) {
      onLog({ kind: "step", id: "highlight", icon: "⏳", text: "Removing text highlighting..." });
      try {
        if (!docRange) docRange = body.getRange();
        docRange.font.highlightColor = null;
        await context.sync();
        changes.push({ icon: "🖍️", text: "Removed all text highlighting" });
        onLog({ kind: "step", id: "highlight", icon: "🖍️", text: "Text highlighting removed" });
      } catch (e) {
        onLog({ kind: "step", id: "highlight", icon: "⚠️", text: "Highlight removal failed", warn: true });
      }
    }

    if (settings.removeEmpty) {
      onLog({ kind: "step", id: "empty", icon: "⏳", text: "Scanning for excess empty paragraphs..." });
      try {
        var paragraphs = body.paragraphs;
        paragraphs.load("text");
        await context.sync();
        // Mark consecutive-blank runs (keep first blank, drop the rest).
        // Skip the very last paragraph — Word treats it specially.
        var toDelete = [];
        var consecutiveEmpty = 0;
        for (var ip = 0; ip < paragraphs.items.length; ip++) {
          var txt = paragraphs.items[ip].text;
          if (/^[\s\xA0]*$/.test(txt)) {
            consecutiveEmpty++;
            if (consecutiveEmpty > 1 && ip < paragraphs.items.length - 1) toDelete.push(ip);
          } else {
            consecutiveEmpty = 0;
          }
        }
        // Each candidate must be checked via OOXML — section/page/column
        // breaks ARE empty paragraphs we MUST keep.
        var ooxmlResults = [];
        for (var d = 0; d < toDelete.length; d++) {
          ooxmlResults.push(paragraphs.items[toDelete[d]].getOoxml());
        }
        if (ooxmlResults.length > 0) await context.sync();
        var safeToDelete = [];
        for (var d2 = 0; d2 < toDelete.length; d2++) {
          try {
            var xmlStr = ooxmlResults[d2].value || "";
            var isBreak = false;
            var wpStart = xmlStr.indexOf("<w:p ");
            if (wpStart === -1) wpStart = xmlStr.indexOf("<w:p>");
            var wpEnd = xmlStr.indexOf("</w:p>");
            var pContent = wpStart !== -1 && wpEnd !== -1 && wpEnd > wpStart ? xmlStr.substring(wpStart, wpEnd) : "";
            var pPrStart = pContent.indexOf("<w:pPr");
            var pPrEnd = pContent.indexOf("</w:pPr>");
            if (pPrStart !== -1 && pPrEnd !== -1 && pPrEnd > pPrStart) {
              var pPrSlice = pContent.substring(pPrStart, pPrEnd);
              if (pPrSlice.indexOf("<w:sectPr") !== -1) isBreak = true;
            }
            if (!isBreak && (pContent.indexOf('w:type="page"') !== -1 || pContent.indexOf('w:type="column"') !== -1)) isBreak = true;
            if (isBreak) continue;
          } catch (eo) { continue; }
          safeToDelete.push(toDelete[d2]);
        }
        var deletedCount = 0;
        for (var d3 = safeToDelete.length - 1; d3 >= 0; d3--) {
          try { paragraphs.items[safeToDelete[d3]].delete(); deletedCount++; }
          catch (ed) { /* skip */ }
          if (d3 % 30 === 0) await context.sync();
        }
        await context.sync();
        if (deletedCount > 0) changes.push({ icon: "✂️", text: "Collapsed " + deletedCount + " excess paragraph gap(s)" });
        onLog({ kind: "step", id: "empty", icon: "✂️", text: "Excess paragraph gaps: " + deletedCount + " collapsed" });
      } catch (e) {
        onLog({ kind: "step", id: "empty", icon: "⚠️", text: "Empty paragraph step failed: " + (e.message || e), warn: true });
      }
    }

    if (settings.fixSpaces) {
      onLog({ kind: "step", id: "spaces", icon: "⏳", text: "Fixing double spacing..." });
      try {
        var spaceCount = await searchReplace(" {2,255}", " ", { matchWildcards: true }, "spaces", null);
        if (spaceCount > 0) changes.push({ icon: "✂️", text: "Fixed " + spaceCount + " double space(s)" });
        onLog({ kind: "step", id: "spaces", icon: "✂️", text: "Double spaces: " + spaceCount + " fixed" });
      } catch (e) {
        onLog({ kind: "step", id: "spaces", icon: "⚠️", text: "Space fix failed", warn: true });
      }
    }

    if (settings.fixPunctuationSpace) {
      onLog({ kind: "step", id: "punct", icon: "⏳", text: "Fixing punctuation spacing..." });
      try {
        var punctSpaceCount = 0;
        var puncts = [".", ",", ";", ":", "!", "?"];
        for (var pp = 0; pp < puncts.length; pp++) {
          try {
            punctSpaceCount += await searchReplace(" " + puncts[pp], puncts[pp], {}, "punct", "Fixing punctuation spaces... {count} corrected");
          } catch (e2) { /* skip punct */ }
        }
        if (punctSpaceCount > 0) changes.push({ icon: "✂️", text: "Fixed " + punctSpaceCount + " space(s) before punctuation" });
        onLog({ kind: "step", id: "punct", icon: "✂️", text: "Punctuation spacing: " + punctSpaceCount + " fixed" });
      } catch (e) {
        onLog({ kind: "step", id: "punct", icon: "⚠️", text: "Punctuation space fix failed", warn: true });
      }
    }

    if (settings.fixDoublePunctuation) {
      onLog({ kind: "step", id: "punct_dbl", icon: "⏳", text: "Fixing double punctuation..." });
      try {
        var doublePunctCount = await searchReplace("\\,{2,255}", ",", { matchWildcards: true }, "punct_dbl", "Fixing double punctuation... {count} corrected");
        // Dots: collapse double-dots only (don't touch ellipses).
        var srDots = body.search("\\.{2,255}", { matchWildcards: true });
        srDots.load("items/text");
        await context.sync();
        for (var jd = 0; jd < srDots.items.length; jd++) {
          if (srDots.items[jd].text === "..") {
            srDots.items[jd].insertText(".", "Replace");
            doublePunctCount++;
          }
        }
        if (doublePunctCount > 0) changes.push({ icon: "✂️", text: "Fixed " + doublePunctCount + " double punctuation mark(s)" });
        onLog({ kind: "step", id: "punct_dbl", icon: "✂️", text: "Double punctuation: " + doublePunctCount + " fixed" });
      } catch (e) {
        onLog({ kind: "step", id: "punct_dbl", icon: "⚠️", text: "Double punctuation fix failed", warn: true });
      }
    }

    if (settings.checkBrackets) {
      onLog({ kind: "step", id: "brackets", icon: "⏳", text: "Scanning for placeholders..." });
      try {
        var srBr = body.search("\\[*\\]", { matchWildcards: true });
        srBr.load("items");
        await context.sync();
        for (var b = 0; b < srBr.items.length; b++) srBr.items[b].load("text");
        await context.sync();
        var bracketFlags = srBr.items.map(function (it) {
          return { text: it.text, searchTerm: it.text, zone: "Body" };
        });
        // XX/XXXX placeholders + TBD + CP-Ref shapes (regex on body text).
        body.load("text");
        await context.sync();
        var bodyText = body.text || "";
        [/\bX{2,}\b/gi, /\bTBD\b/gi, /[A-Z]-\d{4}-(?:TBD|X{2,})/gi].forEach(function (rx) {
          (bodyText.match(rx) || []).forEach(function (m) {
            bracketFlags.push({ text: m, searchTerm: m, zone: "Body" });
          });
        });
        if (bracketFlags.length > 0) {
          warnings.push({ icon: "🔲", label: "Unfilled Placeholders — Body", items: bracketFlags, color: "#e65100", hasLocate: true });
        }
        onLog({ kind: "step", id: "brackets", icon: "🔲", text: "Placeholders scanned: " + bracketFlags.length + " found", warn: bracketFlags.length > 0 });
      } catch (e) {
        onLog({ kind: "step", id: "brackets", icon: "⚠️", text: "Bracket scan failed: " + (e.message || e), warn: true });
      }
    }

    if (settings.checkErrors) {
      onLog({ kind: "step", id: "errors", icon: "⏳", text: "Scanning for broken references..." });
      try {
        var errorMatches = [];
        var srRef = body.search("Error! Reference source not found.", { matchCase: false });
        srRef.load("items/text");
        var srBk = body.search("Error! Bookmark not defined.", { matchCase: false });
        srBk.load("items/text");
        await context.sync();
        [srRef, srBk].forEach(function (sr) {
          for (var je = 0; je < sr.items.length; je++) {
            errorMatches.push({ text: sr.items[je].text, searchTerm: sr.items[je].text, zone: "Body" });
          }
        });
        if (errorMatches.length > 0) {
          warnings.push({ icon: "⚠️", label: "Broken Cross-References", items: errorMatches, color: "#d32f2f", hasLocate: true });
        }
        onLog({ kind: "step", id: "errors", icon: "⚠️", text: "Broken references: " + errorMatches.length + " found", warn: errorMatches.length > 0 });
      } catch (e) {
        onLog({ kind: "step", id: "errors", icon: "⚠️", text: "Error scan failed: " + (e.message || e), warn: true });
      }
    }

    // Header/footer placeholder scan — always runs, regardless of settings.
    onLog({ kind: "step", id: "footer", icon: "⏳", text: "Scanning headers/footers..." });
    var footerFlags = [];
    var hfSections = context.document.sections;
    hfSections.load("items");
    await context.sync();
    var hfPatterns = [
      { rx: /[A-Z]-\d{4}-(?:TBD|X{2,})/gi, label: "CP Ref: " },
      { rx: /\bTBD\b/gi, label: "TBD found in header/footer" },
      { rx: /\bX{2,}\b/gi, label: "XX/XXXX placeholder in header/footer" },
      { rx: /\[[^\]]{0,150}\]/g, label: "Bracket in header/footer: " },
    ];
    var hfTypes = ["Primary", "FirstPage", "EvenPages"];
    for (var sh = 0; sh < hfSections.items.length; sh++) {
      var sec2 = hfSections.items[sh];
      for (var th = 0; th < hfTypes.length; th++) {
        try {
          var hdr = sec2.getHeader(hfTypes[th]);
          hdr.paragraphs.load("items/text");
          var ftr = sec2.getFooter(hfTypes[th]);
          ftr.paragraphs.load("items/text");
          await context.sync();
          var allParagraphs = hdr.paragraphs.items.concat(ftr.paragraphs.items);
          for (var p2 = 0; p2 < allParagraphs.length; p2++) {
            var zoneText = (allParagraphs[p2].text || "").trim();
            if (!zoneText) continue;
            hfPatterns.forEach(function (pat) {
              pat.rx.lastIndex = 0;
              var m = zoneText.match(pat.rx);
              if (m) {
                footerFlags = footerFlags.concat(m.map(function (v) {
                  return { text: pat.label + (pat.label.indexOf(":") > -1 ? v : ""), searchTerm: v };
                }));
              }
            });
          }
        } catch (eh) { /* skip section/type */ }
      }
    }
    // De-dupe by searchTerm.
    footerFlags = footerFlags.filter(function (v, i, a) {
      return a.findIndex(function (x) { return x.searchTerm === v.searchTerm; }) === i;
    });
    if (footerFlags.length > 0) {
      warnings.push({ icon: "📄", label: "Header/Footer Placeholders (" + footerFlags.length + ")", items: footerFlags, color: "#b45309", hasLocate: true });
    }
    onLog({ kind: "step", id: "footer", icon: "📄", text: "Headers/footers scanned: " + footerFlags.length + " flag(s)", warn: footerFlags.length > 0 });
    onLog({ kind: "step", id: "done", icon: "✅", text: "Scrub complete — building report…" });

    // Word count for stats stamp.
    body.load("text");
    await context.sync();
    var words = (body.text || "").split(/\s+/).filter(function (w) { return w.length > 0; }).length;
    return { changes: changes, warnings: warnings, totalWords: words };
  });

  totalWords = report.totalWords;

  // Result with provenance (CLAUDE.md "Result contract" requirement).
  return {
    items: changes,
    warnings: report.warnings,
    totalWords: totalWords,
    overview: changes.length === 0 && report.warnings.length === 0
      ? "No changes needed — document is already clean."
      : "Applied " + changes.length + " fix(es), flagged " + report.warnings.length + " warning(s).",
    provenance: {
      kernelVersion: (typeof window !== "undefined" && window.eli) ? window.eli.kernelVersion : "node",
      toolVersion: "1.0.0",
      timestamp: Date.now(),
      docHash: input && input.docHash || null,
      settings: settings,
    },
  };
}

view.renderSettingsDialog:
function renderSettingsDialog(opts) {
  opts = opts || {};
  var hasRedlines = !!opts.hasRedlines;

  function _checkbox(id, label, checked, variant) {
    return '<label class="_eli3_ds_chk' + (variant === "danger" ? " _eli3_ds_chk_danger" : "") + '">' +
      '<input id="' + id + '" type="checkbox"' + (checked ? " checked" : "") + '>' +
      '<span>' + label + '</span></label>';
  }
  function _collectSettings(ov) {
    function _b(id) { var el = ov.querySelector("#" + id); return el ? el.checked : false; }
    function _v(id) { var el = ov.querySelector("#" + id); return el ? el.value : null; }
    return {
      fontName: _v("_eli3_ds_font"),
      fontSize: parseFloat(_v("_eli3_ds_fontsize")) || 0,
      fontColor: _v("_eli3_ds_fontcolor"),
      removeEmpty: _b("_eli3_ds_removeEmpty"),
      fixSpaces: _b("_eli3_ds_fixSpaces"),
      fixPunctuationSpace: _b("_eli3_ds_fixPunctuationSpace"),
      fixDoublePunctuation: _b("_eli3_ds_fixDoublePunctuation"),
      removeHighlighting: _b("_eli3_ds_removeHighlighting"),
      removeComments: _b("_eli3_ds_removeComments"),
      acceptRedlines: hasRedlines ? _b("_eli3_ds_acceptRedlines") : false,
      checkBrackets: _b("_eli3_ds_checkBrackets"),
      checkErrors: _b("_eli3_ds_checkErrors"),
    };
  }

  return new Promise(function (resolve) {
    showEliDialog({
      variant: "info",
      icon: "🧼",
      title: "Docu-Scrub",
      body:
        '<div style="font-size:12px;color:#64748b;margin-bottom:12px;line-height:1.5">' +
        "Clean up the document and prepare it for execution. Pick which " +
        "passes to run, then click <b>Scrub</b>." +
        "</div>" +
        '<div style="background:#fffbeb;border:1px solid #fcd34d;padding:8px 10px;margin-bottom:12px;font-size:11px;color:#92400e">' +
        "⚠️ Turn off <b>Track Changes</b> in Word before scrubbing." +
        "</div>" +
        // Typography
        '<div class="_eli3_ds_eyebrow">✨ Typography</div>' +
        '<div class="_eli3_ds_typo_row">' +
          '<select id="_eli3_ds_font" class="_eli3_input">' +
            '<option value="Inter">Inter (Premium)</option>' +
            '<option value="Outfit">Outfit (Clean)</option>' +
            '<option value="Times New Roman" selected>Times New Roman</option>' +
            '<option value="Arial">Arial</option>' +
            '<option value="Calibri">Calibri</option>' +
            '<option value="NO_CHANGE">— Keep Original —</option>' +
          '</select>' +
          '<input id="_eli3_ds_fontsize" type="number" value="12" min="6" max="48" class="_eli3_input" style="width:60px">' +
          '<input id="_eli3_ds_fontcolor" type="color" value="#000000" class="_eli3_ds_color">' +
        '</div>' +
        '<div class="_eli3_ds_grid">' +
          '<div>' +
            '<div class="_eli3_ds_eyebrow">🧼 Formatting</div>' +
            _checkbox("_eli3_ds_removeEmpty", "Collapse empty lines", true) +
            _checkbox("_eli3_ds_fixSpaces", "Fix double spaces", true) +
            _checkbox("_eli3_ds_fixPunctuationSpace", "Fix punctuation space", true) +
            _checkbox("_eli3_ds_fixDoublePunctuation", "Fix double punctuation", true) +
            _checkbox("_eli3_ds_removeHighlighting", "Remove highlighting", true) +
          '</div>' +
          '<div>' +
            '<div class="_eli3_ds_eyebrow">🛡️ Review</div>' +
            _checkbox("_eli3_ds_removeComments", "Delete comments", true, "danger") +
            (hasRedlines
              ? _checkbox("_eli3_ds_acceptRedlines", "Accept all redlines", true, "danger")
              : "") +
            '<div class="_eli3_ds_eyebrow" style="margin-top:8px">🚩 Flags</div>' +
            _checkbox("_eli3_ds_checkBrackets", "Placeholders [ ]", true) +
            _checkbox("_eli3_ds_checkErrors", "Broken References", true) +
          '</div>' +
        '</div>',
      buttons: [
        {
          label: "🧼 Scrub Document",
          onclick: function (e, ov) {
            var settings = _collectSettings(ov);
            if (ov.parentNode) ov.parentNode.removeChild(ov);
            resolve(settings);
          },
        },
        {
          label: "Cancel",
          cls: "btn-secondary",
          onclick: function (e, ov) {
            if (ov.parentNode) ov.parentNode.removeChild(ov);
            resolve(null);
          },
        },
      ],
    });
  });
}

// ── Progress overlay ──────────────────────────────────────────────────
// Returns { close, log } — engine calls log() per step via input.onLog.

view.renderProgressOverlay:
function renderProgressOverlay() {
  var ov = document.createElement("div");
  ov.id = "_eli3_ds_progress";
  ov.className = "_eli3_ds_progress";
  ov.innerHTML =
    '<div class="_eli3_ds_progress_card">' +
      '<div class="_eli3_ds_progress_head">' +
        '<div class="_eli3_ds_eyebrow_blue">DOCU-SCRUB</div>' +
        '<div class="_eli3_ds_progress_title">🧼 Cleaning Document…</div>' +
        '<div class="_eli3_ds_progress_bar"><div class="_eli3_ds_progress_sweep"></div></div>' +
      '</div>' +
      '<div id="_eli3_ds_log" class="_eli3_ds_log">' +
        '<div class="_eli3_ds_log_init">Initializing…</div>' +
      '</div>' +
    '</div>';
  document.body.appendChild(ov);
  function close() { if (ov.parentNode) ov.parentNode.removeChild(ov); }
  function log(entry) {
    var logEl = ov.querySelector("#_eli3_ds_log");
    if (!logEl) return;
    var initEl = logEl.querySelector("._eli3_ds_log_init");
    if (initEl) initEl.remove();
    if (entry.kind === "step") {
      var existing = entry.id ? ov.querySelector("#_eli3_ds_log_" + entry.id) : null;
      var text = entry.text || "";
      var color = entry.warn ? "#d97706" : /fixed|accepted|deleted|trimmed|unified|normalized|removed|disabled|complete/.test(text) ? "#16a34a" : "#334155";
      var html =
        '<span class="_eli3_ds_log_icon">' + (entry.icon || "•") + '</span>' +
        '<span class="_eli3_ds_log_text" style="color:' + color + '">' + text + '</span>';
      if (existing) {
        existing.innerHTML = html;
      } else {
        var row = document.createElement("div");
        if (entry.id) row.id = "_eli3_ds_log_" + entry.id;
        row.className = "_eli3_ds_log_row";
        row.innerHTML = html;
        logEl.appendChild(row);
        logEl.scrollTop = logEl.scrollHeight;
      }
    }
    // kind: "flash" — live-update the step text mid-loop. Currently a no-op
    // visually (the final step write already shows the count); kept as an
    // extension point for future per-item progress indicators.
  }
  return { close: close, log: log };
}

// ── Report dialog ─────────────────────────────────────────────────────

view.renderReportDialog:
function renderReportDialog(result) {
  var changes = (result && result.items) || [];
  var warnings = (result && result.warnings) || [];
  var totalWords = (result && result.totalWords) || 0;
  var changesHtml = changes.length
    ? '<ul class="_eli3_ds_changes">' + changes.map(function (c) {
        return '<li><span class="_eli3_ds_change_icon">' + (c.icon || "•") + '</span>' +
          '<span>' + c.text + '</span></li>';
      }).join("") + '</ul>'
    : '<div class="_eli3_ds_empty">No automatic fixes were needed.</div>';
  var warningsHtml = warnings.length
    ? warnings.map(function (w) {
        var items = (w.items || []).slice(0, 12).map(function (it) {
          return '<li>' + (it.text || "") + '</li>';
        }).join("");
        var more = (w.items && w.items.length > 12)
          ? '<li class="_eli3_ds_more">… ' + (w.items.length - 12) + ' more</li>'
          : "";
        return '<div class="_eli3_ds_warn_group" style="border-left-color:' + (w.color || "#d4af37") + '">' +
          '<div class="_eli3_ds_warn_label">' + (w.icon || "🚩") + ' ' + w.label + '</div>' +
          '<ul class="_eli3_ds_warn_items">' + items + more + '</ul>' +
          '</div>';
      }).join("")
    : "";
  showEliDialog({
    variant: warnings.length ? "warning" : "success",
    icon: warnings.length ? "🚩" : "✅",
    title: "Scrub Report",
    body:
      '<div style="font-size:12px;color:#64748b;margin-bottom:8px">' +
      totalWords.toLocaleString() + " words processed" +
      '</div>' +
      '<div class="_eli3_ds_eyebrow">Changes Applied</div>' +
      changesHtml +
      (warnings.length ? '<div class="_eli3_ds_eyebrow" style="margin-top:14px">Flagged for Review</div>' + warningsHtml : ""),
    buttons: [
      {
        label: "Close",
        cls: "btn-secondary",
        onclick: function (e, ov) { if (ov.parentNode) ov.parentNode.removeChild(ov); },
      },
    ],
  });
}

jsonTools.init:
function init(eli) {
  // Find ourselves in the loaded set so we can call analyze + render.
  var bundle = eli.tools._loaded["docuscrub"];
  if (!bundle) return;
  var analyze = bundle._eliEngineFns && bundle._eliEngineFns.analyze;
  var renderSettingsDialog = bundle._eliViewFns && bundle._eliViewFns.renderSettingsDialog;
  var renderProgressOverlay = bundle._eliViewFns && bundle._eliViewFns.renderProgressOverlay;
  var renderReportDialog = bundle._eliViewFns && bundle._eliViewFns.renderReportDialog;
  if (!analyze || !renderSettingsDialog || !renderProgressOverlay || !renderReportDialog) {
    eli.log.event("tool", "docuscrub_init_missing_fns", {
      analyze: !!analyze,
      settings: !!renderSettingsDialog,
      progress: !!renderProgressOverlay,
      report: !!renderReportDialog,
    });
    return;
  }

  function tileHandler() {
    // Detect existing redlines so the settings dialog can offer the
    // "Accept all redlines" option only when relevant.
    var redlinePromise = (eli.host && eli.host.runRaw)
      ? eli.host.runRaw("docuscrub:check_redlines", function (ctx) {
          var ooxml = ctx.document.body.getOoxml();
          return ctx.sync().then(function () {
            var v = ooxml.value || "";
            return v.indexOf("<w:ins ") !== -1 || v.indexOf("<w:del ") !== -1;
          });
        }).catch(function () { return false; })
      : Promise.resolve(false);

    redlinePromise.then(function (hasRedlines) {
      return renderSettingsDialog({ hasRedlines: hasRedlines });
    }).then(function (settings) {
      if (!settings) return; // user cancelled
      eli.fsm.transition("scanning");
      var overlay = renderProgressOverlay();
      var providers = {
        host: eli.host,
        ai: eli.ai,
        storage: eli.storage,
      };
      var input = {
        settings: settings,
        onLog: overlay.log,
        docHash: null, // could hash via host.readText() but skip for now
      };
      analyze(input, providers).then(function (result) {
        overlay.close();
        // Stat record + activity feed entry between engine + view (CLAUDE.md
        // architecture rule: side effects emitted by kernel between engine
        // and view, not from inside either).
        if (eli.stats) {
          eli.stats.record("appOpenedDocuscrub");
          if (result.totalWords) eli.stats.record("wordsFormatted", result.totalWords);
          if (result.items && result.items.length) eli.stats.record("scrubFixes", result.items.length);
        }
        if (eli.activity) {
          var summary;
          if (!result.items.length && !result.warnings.length) {
            summary = "✅ Document already clean";
          } else {
            summary = result.items.length + " fix(es), " + (result.warnings || []).length + " flag(s)";
          }
          eli.activity.add({
            type: "docuscrub",
            icon: "🧼",
            label: "Docu-Scrub",
            summary: summary,
          });
        }
        if (eli.wrongness) {
          eli.wrongness.capture("docuscrub", input, result, {});
        }
        renderReportDialog(result);
        eli.fsm.transition("idle");
      }).catch(function (err) {
        overlay.close();
        eli.fsm.transition("error");
        if (typeof showToast === "function") showToast("Scrub failed: " + (err && err.message || "unknown"), "err");
        eli.log.event("tool", "docuscrub_failed", { error: err && err.message });
        // Reset to idle after surfacing — user can retry.
        setTimeout(function () { try { eli.fsm.transition("idle"); } catch (e) {} }, 100);
      });
    });
  }

  // Register the tile handler matching catalog.id.
  eli.register({ tile: { "app_docuscrub": tileHandler } });
  eli.log.event("tool", "docuscrub_initialized", {});
}
